interface StateMapSvgProps {
  stateName: string;
  className?: string;
}

const StateMapSvg: React.FC<StateMapSvgProps> = ({ stateName, className = "" }) => {
  const mapData = STATE_MAP_PATHS[stateName];
  if (!mapData) return null;

  const gradId = `state-grad-${stateName.replace(/\s+/g, "-").toLowerCase()}`;

  return (
    <svg
      viewBox={mapData.viewBox}
      role="img"
      aria-label={`${stateName} map`}
      className={`w-full h-full max-h-[180px] object-contain transition-transform duration-300 hover:scale-105 ${className}`}
      style={{ filter: "drop-shadow(0 8px 16px rgba(42, 27, 99, 0.16))" }}
    >
      <defs>
        <linearGradient id={gradId} x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="#FFFFFF" />
          <stop offset="100%" stopColor="#F2EEFF" />
        </linearGradient>
      </defs>
      <path
        d={mapData.d}
        fill={`url(#${gradId})`}
        stroke="#2A1B63"
        strokeWidth={3}
        vectorEffect="non-scaling-stroke"
        strokeLinejoin="round"
        strokeLinecap="round"
      />
    </svg>
  );
};

export default StateMapSvg;
